using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using UnityEngine.InputSystem.UI;
namespace IntegratedCampaign {
public class CampaignUI:MonoBehaviour {
 public bool KeepAcrossScenes;public Canvas canvas;public RectTransform root;public Font font;Image fade;Text fadeText;
 protected virtual void Awake(){font=Resources.Load<Font>("Campaign/PixelifySans");var go=new GameObject("Campaign Canvas",typeof(RectTransform),typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));go.transform.SetParent(transform,false);canvas=go.GetComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.sortingOrder=3000;var scaler=go.GetComponent<CanvasScaler>();scaler.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scaler.referenceResolution=new Vector2(1920,1080);scaler.screenMatchMode=CanvasScaler.ScreenMatchMode.Expand;root=go.GetComponent<RectTransform>();}
 public static void EnsureEventSystem(){if(!FindFirstObjectByType<EventSystem>()){var go=new GameObject("UI input",typeof(EventSystem),typeof(InputSystemUIInputModule));}}
 public RectTransform Rect(string name,Transform parent,Vector2 position,Vector2 size){var go=new GameObject(name,typeof(RectTransform));go.transform.SetParent(parent,false);var r=go.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=new Vector2(.5f,.5f);r.pivot=new Vector2(.5f,.5f);r.anchoredPosition=position;r.sizeDelta=size;return r;}
 public Image Image(string name,Transform parent,Vector2 at,Vector2 size,Sprite sprite){var r=Rect(name,parent,at,size);var image=r.gameObject.AddComponent<Image>();image.sprite=sprite;if(sprite&&sprite.border.sqrMagnitude>0)image.type=UnityEngine.UI.Image.Type.Sliced;return image;}
 public Text Label(string name,Transform parent,Vector2 at,Vector2 size,string value,int pixels=32){var r=Rect(name,parent,at,size);var text=r.gameObject.AddComponent<Text>();text.font=font;text.fontSize=pixels;text.alignment=TextAnchor.MiddleCenter;text.color=new Color(1,.94f,.77f);text.text=value;text.raycastTarget=false;text.horizontalOverflow=HorizontalWrapMode.Wrap;return text;}
 public Button Button(string name,Transform parent,Vector2 at,string label,UnityEngine.Events.UnityAction click){var image=Image(name,parent,at,new Vector2(500,100),Resources.Load<Sprite>("Campaign/button"));var button=image.gameObject.AddComponent<Button>();button.transition=Selectable.Transition.SpriteSwap;button.spriteState=new SpriteState{highlightedSprite=Resources.Load<Sprite>("Campaign/button_hover"),pressedSprite=Resources.Load<Sprite>("Campaign/button_pressed"),selectedSprite=Resources.Load<Sprite>("Campaign/button_hover")};Label("Label",image.transform,Vector2.zero,new Vector2(430,70),label,32);button.onClick.AddListener(click);return button;}
 public void ShowFade(float alpha,string text){if(!fade){fade=Image("Fade",root,Vector2.zero,new Vector2(6000,6000),null);fadeText=Label("Transition label",fade.transform,Vector2.zero,new Vector2(1400,200),text,44);}fade.color=new Color(0,0,0,alpha);fadeText.text=text;fadeText.color=new Color(1,1,1,alpha);}
}
}
